                    },
                },
                "Test": {
                    "Jenkins": {
                        "InputArtifacts": {"minItems": 0, "maxItems": 5},
                        "OutputArtifacts": {"minItems": 0, "maxItems": 5},
                    },
                },
            },
        }

    def validate(
        self, validator: Validator, keywords: Any, instance: Any, schema: dict[str, Any]
    ) -> ValidationResult:
